CREATE OR REPLACE FUNCTION public.jogo_proxima_rodada()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ultima rodadas; v_prox int;
begin
  if not sou_admin() then raise exception 'Apenas admin'; end if;
  select * into v_ultima from rodadas order by ordem desc limit 1;
  if v_ultima.id is not null and v_ultima.status <> 'revelada' then
    raise exception 'Revele a rodada atual antes de abrir a próxima';
  end if;
  v_prox := coalesce(v_ultima.ordem + 1, 0);
  if v_prox >= (select count(*) from sorteio) then
    raise exception 'Todas as rodadas já foram jogadas';
  end if;
  insert into rodadas (sorteio_id, ordem)
  select id, v_prox from sorteio where posicao_circulo = v_prox;
end $function$

CREATE OR REPLACE FUNCTION public.jogo_revelar()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rodada rodadas; v_amigo uuid;
begin
  if not sou_admin() then raise exception 'Apenas admin'; end if;
  select * into v_rodada from rodadas order by ordem desc limit 1;
  if v_rodada.status <> 'encerrada' then
    raise exception 'Encerre a votação antes de revelar';
  end if;
  select quem_recebe_id into v_amigo from sorteio where id = v_rodada.sorteio_id;
  update palpites set acertou = (chute_id = v_amigo) where rodada_id = v_rodada.id;
  update rodadas set status = 'revelada' where id = v_rodada.id;
end $function$

CREATE OR REPLACE FUNCTION public.realizar_sorteio(p_primeiro text, p_segundo text, p_tentativas integer DEFAULT 5000)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_primeiro uuid; v_segundo uuid; v_ordem uuid[]; v_n int; v_ok boolean; i int; t int;
begin
  if exists (select 1 from sorteio) then
    raise exception 'O sorteio já foi realizado';
  end if;

  select id into v_primeiro from participantes where email = lower(p_primeiro);
  select id into v_segundo  from participantes where email = lower(p_segundo);
  if v_primeiro is null or v_segundo is null then
    raise exception 'Participante não encontrado';
  end if;

  for t in 1..p_tentativas loop
    select array[v_primeiro, v_segundo] || array_agg(id order by random())
      into v_ordem
      from participantes where id not in (v_primeiro, v_segundo);
    v_n := array_length(v_ordem, 1);
    v_ok := true;

    for i in 1..v_n loop
      if exists (select 1 from exclusoes e
                 where (e.participante_a = v_ordem[i] and e.participante_b = v_ordem[i % v_n + 1])
                    or (e.participante_b = v_ordem[i] and e.participante_a = v_ordem[i % v_n + 1])) then
        v_ok := false;
        exit;
      end if;
    end loop;

    if v_ok then
      insert into sorteio (quem_da_id, quem_recebe_id, posicao_circulo)
      select v_ordem[g], v_ordem[g % v_n + 1], g - 1
        from generate_series(1, v_n) g;
      return format('Sorteio realizado: %s participantes em círculo.', v_n);
    end if;
  end loop;

  raise exception 'Não foi possível montar um círculo respeitando as exclusões';
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.votar(p_chute uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_eu uuid := meu_participante_id(); v_rodada rodadas; v_revelador uuid;
begin
  if v_eu is null then raise exception 'Somente participantes votam'; end if;
  select * into v_rodada from rodadas order by ordem desc limit 1;
  if v_rodada.id is null or v_rodada.status <> 'votando' then
    raise exception 'A votação está fechada';
  end if;
  select quem_da_id into v_revelador from sorteio where id = v_rodada.sorteio_id;
  if v_eu = v_revelador then raise exception 'Você não vota na sua própria rodada'; end if;
  if p_chute = v_revelador then raise exception 'Ninguém tira a si mesmo'; end if;

  insert into palpites (rodada_id, votante_id, chute_id)
  values (v_rodada.id, v_eu, p_chute)
  on conflict (rodada_id, votante_id)
  do update set chute_id = excluded.chute_id, criado_em = now();
end $function$
